#include <iostream>#include <cstring>#include "clsClientes.h"using namespace std;// CONSTRUCTORCliente::Cliente() {    DNI = 0;    NombreApellido[0] = '\0';    Telefono = 0;    Estado = false;}// SETTERSvoid Cliente::setDNI(int dni) {    DNI = dni;}void Cliente::setNombreApellido(const char *nombape) {    strcpy(NombreApellido, nombape);}void Cliente::setTelefono(int tel) {    Telefono = tel;}void Cliente::setEstado(bool est) {    Estado = est;}// GETTERSint Cliente::getDNI() {    return DNI;}const char *Cliente::getNombreApellido() {    return NombreApellido;}int Cliente::getTelefono() {    return Telefono;}bool Cliente::getEstado() {    return Estado;}// CARGARvoid Cliente::Cargar() {    cout << "INGRESE EL DNI DEL CLIENTE: ";    cin >> DNI;    cout << "INGRESE EL NOMBRE Y APELLIDO: ";    cin.ignore();    cin.getline(NombreApellido, 50);    cout << "INGRESE EL NUMERO DE TELEFONO: ";    cin >> Telefono;    Estado = true;}// MOSTRARvoid Cliente::Mostrar() {    if (Estado) {        cout << "DNI DEL CLIENTE : " << DNI << endl;        cout << "NOMBRE Y APELLIDO  : " << NombreApellido << endl;        cout << "TELEFONO: " << Telefono << endl;    }}